export type getBeerResponse200 = {
  data: BeerDetailsDto
  status: 200
}

export type getBeerResponse400 = {
  data: Problem
  status: 400
}

export type getBeerResponse404 = {
  data: Problem
  status: 404
}

export type getBeerResponse500 = {
  data: Problem
  status: 500
}

export type getBeerResponseSuccess = (getBeerResponse200) & {
  headers: Headers;
};
export type getBeerResponseError = (getBeerResponse400 | getBeerResponse404 | getBeerResponse500) & {
  headers: Headers;
};

export type getBeerResponse = (getBeerResponseSuccess | getBeerResponseError)

export const getGetBeerUrl = (id: string,) => {




  return `/api/v1/beers/${encodeURIComponent(String(id))}`
}

/**
 * Full details for a single beer, including its brewery.
 * @summary Get beer details
 */
export const getBeer = async (id: string, options?: Parameters<typeof kaliaFetch>[1]): Promise<getBeerResponse> => {

  return kaliaFetch<getBeerResponse>(getGetBeerUrl(id),
  {
    ...options,
    method: 'GET'


  }
);}





export const getGetBeerQueryKey = (id: string,) => {
    return [
    `/api/v1/beers/${id}`
    ] as const;
    }


export const getGetBeerQueryOptions = <TData = Awaited<ReturnType<typeof getBeer>>, TError = Problem>(id: string, options?: { query?:Partial<UseQueryOptions<Awaited<ReturnType<typeof getBeer>>, TError, TData>>, request?: SecondParameter<typeof kaliaFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getGetBeerQueryKey(id);



    const queryFn: QueryFunction<Awaited<ReturnType<typeof getBeer>>> = ({ signal }) => getBeer(id, { signal, ...requestOptions });





   return  { queryKey, queryFn, enabled: id !== null && id !== undefined, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof getBeer>>, TError, TData> & { queryKey: DataTag<QueryKey, TData, TError> }
}

